pragma solidity ^0.8.33;

import '../../modules/decentralized-resolution-module/DecentralizedResolverStructs.sol';

/**
 * @title IIncentiveModule
 * @notice Interface for swappable incentive modules in decentralized resolution system
 * @dev Defines the contract between DecentralizedResolutionModule and incentive logic
 *      - V1: Performance-based workload routing (no appeal bonds)
 *      - V2: Appeal bonds + escalation cost curves (no resolver staking)
 *      - V3: Resolver staking, slashing, delegation (future)
 */
interface IIncentiveModule {
    // ============ Core Lifecycle Hooks ============

    /**
     * @notice Called when a dispute is opened
     * @param workflowId Unique identifier for the dispute
     * @param escrowContract Address of the vault
     * @param token Token address for escrow
     * @param amount Escrow amount
     * @param escrowFee Fee collected from escrow
     * @param round Current round (0=initial)
     */
    function onDisputeOpened(
        uint256 workflowId,
        address escrowContract,
        address token,
        uint256 amount,
        uint256 escrowFee,
        uint8 round
    ) external;

    /**
     * @notice Called when a resolver is assigned to a dispute
     * @param workflowId Unique identifier for the dispute
     * @param escrowContract Address of the vault
     * @param resolver Address of assigned resolver
     * @param round Current round
     */
    function onResolverAssigned(
        uint256 workflowId,
        address escrowContract,
        address resolver,
        uint8 round
    ) external;

    /**
     * @notice Called when a resolver submits a decision
     * @param workflowId Unique identifier for the dispute
     * @param escrowContract Address of the vault
     * @param resolver Address of resolver
     * @param round Current round
     * @param decision Resolution outcome
     * @param responseTime Time taken to resolve (seconds)
     */
    function onDecisionSubmitted(
        uint256 workflowId,
        address escrowContract,
        address resolver,
        uint8 round,
        ResolutionOutcome decision,
        uint256 responseTime
    ) external;

    /**
     * @notice Called when a dispute is escalated to the next round
     * @param workflowId Unique identifier for the dispute
     * @param escrowContract Address of the vault
     * @param fromRound Previous round
     * @param toRound Next round
     * @param escalatedBy Address that initiated escalation
     */
    function onEscalated(
        uint256 workflowId,
        address escrowContract,
        uint8 fromRound,
        uint8 toRound,
        address escalatedBy
    ) external;

    /**
     * @notice Called when a dispute is finalized (no more appeals)
     * @param workflowId Unique identifier for the dispute
     * @param escrowContract Address of the vault
     * @param finalRound Final round that decided the outcome
     * @param finalDecision Final resolution outcome
     */
    function onDisputeFinalized(
        uint256 workflowId,
        address escrowContract,
        uint8 finalRound,
        ResolutionOutcome finalDecision
    ) external;

    /**
     * @notice Called when a resolver times out
     * @param workflowId Unique identifier for the dispute
     * @param escrowContract Address of the vault
     * @param resolver Address of resolver that timed out
     * @param round Round where timeout occurred
     * @param timeoutType Type of timeout (accept=0, resolve=1)
     */
    function onResolverTimeout(
        uint256 workflowId,
        address escrowContract,
        address resolver,
        uint8 round,
        uint8 timeoutType
    ) external;

    // ============ Payment Distribution ============

    /**
     * @notice Calculate and distribute resolver payments for a finalized dispute
     * @param workflowId Unique identifier for the dispute
     * @param escrowContract Address of the vault
     * @param token Token address for payment
     * @param totalFees Total fees available for distribution
     */
    function distributePayments(
        uint256 workflowId,
        address escrowContract,
        address token,
        uint256 totalFees
    ) external;

    /**
     * @notice Get claimable payment for a resolver
     * @param workflowId Unique identifier for the dispute
     * @param escrowContract Address of the vault
     * @param resolver Resolver address
     * @return amount Claimable amount
     */
    function getClaimablePayment(
        uint256 workflowId,
        address escrowContract,
        address resolver
    ) external view returns (uint256 amount);

    // ============ V2+ Functions (optional in V1) ============

    /**
     * @notice Check if module supports a specific feature
     * @param featureId Feature identifier (bytes4 keccak256 hash)
     * @return supported Whether the feature is supported
     * @dev Feature IDs (defined as constants in implementations):
     *      - FEATURE_APPEAL_BONDS = bytes4(keccak256("APPEAL_BONDS_V1"))
     *        Indicates module supports appeal bonds for escalation
     *      - FEATURE_PULL_ERC20_BONDS = bytes4(keccak256("PULL_ERC20_BONDS_V1"))
     *        Indicates module uses pull-based pattern for ERC20 bonds (safeTransferFrom)
     * @dev V1 implementations should return false for all features
     * @dev V2+ implementations should return true for supported features
     */
    function supportsFeature(bytes4 featureId) external view returns (bool supported);

    /**
     * @notice Get required appeal bond for escalation (V2+)
     * @param workflowId Unique identifier for the dispute
     * @param escrowContract Address of the vault
     * @param fromRound Current round
     * @param toRound Next round
     * @return bondAmount Required bond amount
     * @return token Token address for bond
     * @dev V1 implementations should return (0, address(0))
     */
    function getRequiredAppealBond(
        uint256 workflowId,
        address escrowContract,
        uint8 fromRound,
        uint8 toRound
    ) external view returns (uint256 bondAmount, address token);

    /**
     * @notice Record appeal bond payment (V2+)
     * @param workflowId Unique identifier for the dispute
     * @param escrowContract Address of the vault
     * @param depositor Address that deposited bond (for ERC20: escrow contract, for ETH: user/escalator)
     * @param escalatedBy Address that initiated the escalation (always the user/escalator)
     * @param amount Bond amount
     * @param token Token address (address(0) = ETH)
     * @param round Round being appealed to
     * @dev V1 implementations should revert
     * @dev SHOULD only be callable by the escrow contract or resolution module (enforced by implementation)
     * @dev For ETH bonds (token == address(0)): MUST be payable and require(msg.value == amount)
     *      For ETH bonds, depositor MUST equal escalatedBy (user-funded)
     * @dev For ERC20 bonds: Implementation MUST pull tokens via safeTransferFrom(depositor, address(this), amount)
     *      and MUST revert on transfer failure. Depositor is typically the escrow contract (escrow-funded),
     *      but escalatedBy tracks the actual escalator for metrics/accounting.
     */
    function recordAppealBond(
        uint256 workflowId,
        address escrowContract,
        address depositor,
        address escalatedBy,
        uint256 amount,
        address token,
        uint8 round
    ) external payable;

    /**
     * @notice Distribute appeal bond based on outcome (V2+)
     * @param workflowId Unique identifier for the dispute
     * @param escrowContract Address of the vault
     * @param round Round that was appealed
     * @param outcomeFlipped Whether the appeal succeeded
     * @dev V1 implementations should revert
     */
    function distributeAppealBond(
        uint256 workflowId,
        address escrowContract,
        uint8 round,
        bool outcomeFlipped
    ) external;
}","keccak256":"0x5fdb856acf52fc6c9815bc524babd8797edc49ca8c9fb58f9b38adb738120968","license":"Apache-2.0"},"contracts/shared/interfaces/IResolutionModule.sol":{"content":"// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.33;

import '@openzeppelin/contracts/utils/introspection/IERC165.sol';
import '../../types/EscrowTypes.sol';

/**
 * @title IResolutionModule
 * @notice Interface for dispute resolution modules
 * @dev Handles resolution logic including escalation paths, resolver roles, and dynamic resolution
 *      All resolution modules must implement ERC-165 for interface detection
 */
interface IResolutionModule is IERC165 {
    /**
     * @notice Initialize a new dispute in the module
     * @param workflowId The escrow transfer ID
     * @param escrowContract Address of the vault
     * @param initialResolver Address of initial resolver
     * @param categoryKey Category identifier for round-robin assignment
     */
    function initializeDispute(
        uint256 workflowId,
        address escrowContract,
        address initialResolver,
        bytes32 categoryKey
    ) external;

    /**
     * @notice Record a resolution outcome
     * @param workflowId The escrow transfer ID
     * @param escrowContract Address of the vault
     * @param resolver Address of resolver who made the decision
     * @param outcome The resolution outcome (RELEASE or CANCEL)
     * @param resolutionTime Time taken to resolve
     */
    function recordResolution(
        uint256 workflowId,
        address escrowContract,
        address resolver,
        ResolutionOutcome outcome,
        uint256 resolutionTime
    ) external;

    /**
     * @notice Check if an address is authorized to resolve a dispute
     * @param workflowId The escrow transfer ID
     * @param escrowContract Address of the vault
     * @param disputeResolver The address attempting to resolve
     * @param escrowData Encoded escrow data
     * @return authorized True if authorized
     * @return role The dispute resolver role (0 = standard resolver, 1 = senior resolver, etc.)
     */
    function isAuthorizedDisputeResolver(
        uint256 workflowId,
        address escrowContract,
        address disputeResolver,
        bytes calldata escrowData
    ) external view returns (bool authorized, uint8 role);

    /**
     * @notice Get the appropriate dispute resolver for a dispute
     * @param workflowId The escrow transfer ID
     * @param escrowContract Address of the vault
     * @param escrowData Encoded escrow data
     * @return disputeResolver The dispute resolver address
     * @return escalationLevel Current escalation level (0 = initial, 1+ = escalated)
     */
    function getDisputeResolver(
        uint256 workflowId,
        address escrowContract,
        bytes calldata escrowData
    ) external view returns (address disputeResolver, uint8 escalationLevel);

    /**
     * @notice Check if escalation is allowed and get next resolver
     * @param workflowId The escrow transfer ID
     * @param escrowContract Address of the vault
     * @param currentLevel Current escalation level
     * @param escrowData Encoded escrow data
     * @return canEscalate True if escalation is allowed
     * @return nextDisputeResolver Address of next dispute resolver (address(0) if cannot escalate)
     * @return escalationFee Fee required for escalation (0 if none)
     */
    function canEscalate(
        uint256 workflowId,
        address escrowContract,
        uint8 currentLevel,
        bytes calldata escrowData
    ) external view returns (bool canEscalate, address nextDisputeResolver, uint256 escalationFee);

    /**
     * @notice Execute escalation to next level
     * @param workflowId The escrow transfer ID
     * @param escrowContract Address of the vault
     * @param escrowData Encoded escrow data
     * @return success True if escalation was successful
     * @return newDisputeResolver Address of new dispute resolver
     * @return newLevel New escalation level
     */
    function executeEscalation(
        uint256 workflowId,
        address escrowContract,
        bytes calldata escrowData
    ) external returns (bool success, address newDisputeResolver, uint8 newLevel);

    /**
     * @notice Get required appeal bond for escalation (DR v2)
     * @param workflowId The escrow transfer ID
     * @param escrowContract Address of the vault
     * @param currentLevel Current escalation level
     * @param escrowData Encoded escrow data
     * @return amount Bond amount required (0 if bonds not enabled)
     * @return token Token address for bond (address(0) if native token)
     */
    function getRequiredAppealBond(
        uint256 workflowId,
        address escrowContract,
        uint8 currentLevel,
        bytes calldata escrowData
    ) external view returns (uint256 amount, address token);

    /**
     * @notice Get decision at a specific round
     * @param workflowId Dispute ID
     * @param escrowContract Address of the vault
     * @param round Round to check
     * @return decision ResolutionOutcome enum value
     */
    function getDecisionAtRound(uint256 workflowId, address escrowContract, uint8 round) external view returns (uint8 decision);

    /**
     * @notice Get appeal deadline and current round
     * @param workflowId Dispute ID
     * @param escrowContract Address of the vault
     * @return appealDeadline Appeal deadline for current round
     * @return currentRound Current round
     * @return isFinalRound True if this is the final round
     */
    function getAppealDeadlineAndRound(
        uint256 workflowId,
        address escrowContract
    ) external view returns (uint256 appealDeadline, uint8 currentRound, bool isFinalRound);

    /**
     * @notice Record a reversal
     * @param workflowId Dispute ID
     * @param escrowContract Address of the vault
     * @param priorRound Round where original decision was made
     */
    function recordReversal(uint256 workflowId, address escrowContract, uint8 priorRound) external;

    /**
     * @notice Finalize a dispute
     * @param workflowId Dispute ID
     * @param escrowContract Address of the vault
     */
    function finalizeDispute(uint256 workflowId, address escrowContract) external;

    /**
     * @notice Get the module name/identifier
     * @return name The module name
     */
    function moduleName() external pure returns (string memory name);

    /**
     * @notice Get the module version
     * @return version The module version (semantic versioning, e.g., "1.0.0")
     * @dev Must follow semantic versioning: MAJOR.MINOR.PATCH
     *      Major version changes indicate breaking changes
     */
    function moduleVersion() external pure returns (string memory version);
